-- EcoLens: fotos licenciadas das espécies e seus créditos.
-- GERADO por tool/build_species_photos_migration.py a partir de
-- supabase/data/plant_photos.json. Não edite à mão.

alter table public.species
  add column if not exists image_credit text,
  add column if not exists image_source_url text,
  add column if not exists image_license_url text,
  add column if not exists image_license_label text;

-- Créditos das fotos que já estavam publicadas.

-- Fotos das fichas do catálogo curado.
update public.species set image_url = 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/09/Yellow_oleander_%28Cascabela_thevetia%29_flower.jpg/500px-Yellow_oleander_%28Cascabela_thevetia%29_flower.jpg', image_credit = 'David E Mead', image_source_url = 'https://commons.wikimedia.org/wiki/File:Yellow_oleander_(Cascabela_thevetia)_flower.jpg', image_license_url = 'https://creativecommons.org/publicdomain/zero/1.0', image_license_label = 'CC0' where slug = 'thevetia-peruviana';
